            return face == BlockFace.UP && block.isPowered() ? 15 : 0;
        } else if (block.getType() == StateTypes.OBSERVER) {
            return block.getFacing() == face && block.isPowered() ? 15 : 0;
        } else if (block.getType() == StateTypes.REPEATER) {
